import {GuidedRecorder,AIM_STAGES,SHOT_ATTEMPTS} from './recorder.js?v=spiral-14';
import {sessionStore} from './storage.js?v=loading-17';
const $=id=>document.getElementById(id),recorder=new GuidedRecorder({timeOriginEpochMs:performance.timeOrigin}),store=sessionStore(document.documentElement.dataset.debugTest==='true');
const modeInfo={shooting:{label:'Shot',count:'debugShotCount',export:'debugShotExport',file:'chickenshot-shooting-10-attempts.json'},'aim-only':{label:'Aim-only',count:'debugAimCount',export:'debugAimExport',file:'chickenshot-aim-only-paths.json'},stillness:{label:'Hold-still',count:'debugStillCount',export:'debugStillExport',file:'chickenshot-hold-still.json'}};
let lastFrame=null,selected='shooting',lastCue='',lastPartKey='',trace=[];
const tell=text=>$('debugStatus').textContent=text;
function cue(text){if(text===lastCue)return;lastCue=text;$('debugCue').textContent=text;$('debugPanelCue').textContent=text;}
function modeEvent(){document.dispatchEvent(new CustomEvent('chickenshot:debug-mode',{detail:{mode:recorder.active?.mode??(recorder.trailingCapture?'shooting':null)}}));}
function renderSaved(){
 for(const [mode,info] of Object.entries(modeInfo)){const session=recorder.sessions[mode],shot=mode==='shooting';$(info.count).textContent=mode==='stillness'?(session?`${session.status} · ${session.parts[0]?.summary.stillness.samples??0} hold samples`:'No hold recorded'):session?`${session.parts.length}/${session.protocol.expectedParts} ${shot?'attempts':'paths'} · ${session.status}`:`0/${shot?10:AIM_STAGES.length} ${shot?'attempts':'paths'}`;$(info.export).disabled=!(session?.parts.length||session?.unfinishedPart)||!!(shot&&recorder.trailingCapture);}
 const session=recorder.export(selected);$('debugFrameData').textContent=JSON.stringify(session??{mode:selected,mediaIncluded:false,parts:[]},null,2);$('debugView').value=selected;
 const parts=[...(session?.parts??[]),...(session?.unfinishedPart?[session.unfinishedPart]:[])],shots=parts.reduce((n,p)=>n+(p.summary?.actualShots??0),0),hold=session?.parts[0]?.summary.stillness;
 const holdText=hold?` Stationary hold: ${hold.samples} samples · crosshair span ${((hold.channels['aim.x']?.span??0)*100).toFixed(1)}% horizontal / ${((hold.channels['aim.y']?.span??0)*100).toFixed(1)}% vertical.`:'';
 $('debugSummary').textContent=session?`${modeInfo[selected].label} file: ${session.parts.length} completed parts · ${shots} detected shot(s). ${session.shotReview?`${session.shotReview.matchedByTiming} timing matches · ${session.shotReview.unmatchedAttempts} missed · ${session.shotReview.unwantedShots} unwanted.`:selected!=='shooting'?'All shots here are unwanted.':'No Done confirmations yet.'}${holdText} Full 21-point hand coordinates included.`:'No session saved in this mode yet.';
}
async function persist(mode){try{await store.save(mode,recorder.export(mode));$('debugStorage').textContent='Saved on this device. Shooting, aim-only and hold-still data are stored separately. No upload.';}catch{$('debugStorage').textContent='Could not save locally. Keep this page open and export your files.';}renderSaved();}
function start(mode){
 if(!lastFrame||performance.now()-lastFrame.arrivedAt>2500){tell('First enable the camera. Your whole hand must be visible.');return;}if(lastFrame.phase!=='running'){tell('Start or resume the round first.');return;}
 if(recorder.sessions[mode]?.parts.length||recorder.sessions[mode]?.unfinishedPart){tell('This mode already has saved data. Export or clear it before starting again.');return;}
 try{recorder.start(mode,performance.now());selected=mode;lastPartKey='';$('debugNote').value='';modeEvent();renderSaved();}catch(e){tell(e.message);}
}
function done(){try{const result=recorder.done(performance.now(),$('debugNote').value);$('debugNote').value='';selected=result.mode;lastPartKey='';void persist(result.mode);if(result.mode==='shooting')setTimeout(()=>{recorder.finalize(performance.now());modeEvent();void persist('shooting');},850);if(result.complete){modeEvent();cue(result.mode==='shooting'?'ALL 10 ATTEMPTS SAVED · EXPORT SHOTS':'AIM PATHS SAVED · EXPORT AIM ONLY');tell(result.mode==='shooting'?'Ten intended gestures confirmed. Collecting the last delayed tracking frames briefly, then export the shooting file.':'Rectangle, X, circle, expanding spiral, plus, random aiming and centre are saved separately from shooting. Export the aim-only file.');}}catch(e){tell(e.message);}}
function stop(){const result=recorder.stop(performance.now(),$('debugNote').value);if(result){selected=result.mode;modeEvent();void persist(result.mode);cue(result.mode==='stillness'?'HOLD SAVED · EXPORT HOLD STILL':'SESSION STOPPED · DATA KEPT SEPARATELY');tell(result.mode==='stillness'?'Your hold is saved separately with all hand landmarks, crosshair drift and unwanted shots. Export HOLD STILL.':'Completed parts and the unfinished part are kept. Export this mode before clearing it.');}}
$('debugShot').addEventListener('click',()=>start('shooting'));$('debugAim').addEventListener('click',()=>start('aim-only'));$('debugStill').addEventListener('click',()=>start('stillness'));$('debugDone').addEventListener('click',done);$('debugStop').addEventListener('click',stop);
$('debugView').addEventListener('change',e=>{selected=e.target.value;renderSaved();});
async function clearMode(mode){if(recorder.active||recorder.trailingCapture){tell('Finish or stop the active session and wait for its last frames first.');return;}recorder.sessions[mode]=null;try{await store.save(mode,null);}catch{}renderSaved();tell(`${modeInfo[mode].label} data cleared.`);}
$('debugClearShots').addEventListener('click',()=>void clearMode('shooting'));$('debugClearAim').addEventListener('click',()=>void clearMode('aim-only'));$('debugClearStill').addEventListener('click',()=>void clearMode('stillness'));
function download(mode){const session=recorder.export(mode);if(!session)return;const url=URL.createObjectURL(new Blob([JSON.stringify(session,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=modeInfo[mode].file;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('debugShotExport').addEventListener('click',()=>download('shooting'));$('debugAimExport').addEventListener('click',()=>download('aim-only'));$('debugStillExport').addEventListener('click',()=>download('stillness'));
document.addEventListener('chickenshot:tracking',event=>{lastFrame=event.detail;recorder.push(lastFrame);if(recorder.active&&lastFrame.state){trace.push([lastFrame.state.aimX*100,lastFrame.state.aimY*100]);trace=trace.slice(-1500);}});
document.addEventListener('chickenshot:diagnostic',event=>recorder.diagnose(event.detail));
document.addEventListener('keydown',event=>{if(event.repeat||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||$('helpDialog').open)return;if(event.key==='Enter'&&recorder.active&&recorder.active.mode!=='stillness'){event.preventDefault();done();}if(event.key.toLowerCase()==='t'){event.preventDefault();start('shooting');}if(event.key.toLowerCase()==='a'){event.preventDefault();start('aim-only');}if(event.key.toLowerCase()==='h'){event.preventDefault();start('stillness');}});
const connections=[[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17]],skeleton=$('debugSkeleton'),sctx=skeleton.getContext('2d');
function drawHand(frame){sctx.clearRect(0,0,240,160);const points=frame?.imageLandmarks;if(!points?.length){sctx.fillStyle='#abc49f';sctx.font='12px sans-serif';sctx.fillText('Show your whole hand',48,85);return;}
 const x=i=>(1-points[i][0])*240,y=i=>points[i][1]*160;
 sctx.lineWidth=2;for(const [n,ids] of connections.entries()){sctx.strokeStyle=['#ffd279','#ffe8b5','#b8e09b','#8fd2bf','#a5c6ec','#b8e09b'][n];sctx.beginPath();ids.forEach((id,i)=>i?sctx.lineTo(x(id),y(id)):sctx.moveTo(x(id),y(id)));sctx.stroke();}for(let i=0;i<points.length;i++){sctx.fillStyle=i===0?'#ffd279':'#eff5d8';sctx.beginPath();sctx.arc(x(i),y(i),2.8,0,Math.PI*2);sctx.fill();}}
setInterval(()=>{
 const now=performance.now(),active=recorder.active;const busy=!!active||!!recorder.trailingCapture;$('debugShot').disabled=busy;$('debugAim').disabled=busy;$('debugStill').disabled=busy;$('debugDone').disabled=!active||active.mode==='stillness'||now<active.part.cueAt;$('debugStop').textContent=active?.mode==='stillness'?'Stop holding & save':'Stop session';$('debugDone').hidden=active?.mode==='stillness';$('debugStop').classList.toggle('main',active?.mode==='stillness');$('debugStop').style.gridColumn=active?.mode==='stillness'?'1 / -1':'';$('debugStop').disabled=!active;
 if(active){const p=active.part,key=`${active.session.createdAt}/${p.number}`,stage=active.mode==='aim-only'?AIM_STAGES[p.number-1]:null,holding=active.mode==='stillness';if(key!==lastPartKey){lastPartKey=key;trace=[];$('debugGuidePath').setAttribute('d',stage?.path??'');$('debugTraceHint').textContent=holding?'LIVE CROSSHAIR · DO NOT CHASE IT':'LIVE CROSSHAIR · FOLLOW THE GUIDE';$('debugGuideTitle').textContent=holding?'Stationary hold · no aiming or shooting':stage?`${p.number}/${AIM_STAGES.length} · ${stage.title}`:`Attempt ${p.number}/${SHOT_ATTEMPTS}`;}
 const countdown=Math.ceil((p.cueAt-now)/1000);cue(countdown>0?`GET COMFORTABLE · ${countdown}`:holding?'HOLD STILL · DO NOT CHASE THE CROSSHAIR':stage?`${stage.title.toUpperCase()} · DO NOT SHOOT`:`SHOOT ${p.number}/10 · THEN PRESS DONE`);
 tell(countdown>0?'Get comfortable. Small movement is fine.':holding?`${p.instruction} Recording ${Math.max(0,Math.floor((now-p.cueAt)/1000))} seconds. No time limit.`:`${p.instruction} Nothing advances until you press Done or Enter.`);
 if(holding){const channels=p.stillness.channels,span=axis=>{const c=channels['aim.'+axis];return ((c?c.max-c.min:0)*100).toFixed(1);};$('debugStillCount').textContent=`Recording · ${p.stillness.samples} samples · crosshair span ${span('x')}% horizontal / ${span('y')}% vertical · ${p.stillness.unwantedShots} unwanted shots`;}
 $('debugDone').textContent=holding?'Hold continues until Stop':stage?`Done — next path (${p.number}/${AIM_STAGES.length})`:`Done — I attempted shot ${p.number}/10`;
 }
 if(lastFrame){const f=lastFrame;$('debugAimDot').style.left=`${f.state.aimX*100}%`;$('debugAimDot').style.top=`${f.state.aimY*100}%`;$('debugTrace').setAttribute('points',trace.map(p=>p.join(',')).join(' '));$('debugLive').textContent=now-f.arrivedAt>2500?'No recent tracking updates.':`${f.reason.replaceAll('-',' ')} · ${f.before.shells} shells · ${Math.round(f.frameAgeMs)} ms frame age`;$('debugReady').textContent=f.state.armed?'READY':f.state.returnRequired?'LOWER SLIGHTLY':f.state.pose?'GETTING READY':f.state.aimValid?'AIM ONLY':'SHOW YOUR WHOLE HAND';drawHand(f);}
},100);
try{for(const mode of Object.keys(modeInfo))recorder.restore(mode,await store.load(mode));}catch{$('debugStorage').textContent='Local storage unavailable; export your files before closing.';}
renderSaved();$('debugShot').disabled=false;$('debugAim').disabled=false;$('debugStill').disabled=false;cue('ENABLE CAMERA · CHOOSE ONE MODE');tell('Ready. Shooting, aim-only and hold-still sessions have separate exports.');
